class Invoice extends DataClass implements Insertable<Invoice> {
  final String id;
  final String school;
  final int year;
  final int term;
  final String? fee;
  final String? description;
  final int student;
  final double amount;
  final InvoiceStatus status;
  final BigInt? due;
  final BigInt created;
  final BigInt updated;
  const Invoice({
    required this.id,
    required this.school,
    required this.year,
    required this.term,
    this.fee,
    this.description,
    required this.student,
    required this.amount,
    required this.status,
    this.due,
    required this.created,
    required this.updated,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['school'] = Variable<String>(school);
    map['year'] = Variable<int>(year);
    map['term'] = Variable<int>(term);
    if (!nullToAbsent || fee != null) {
      map['fee'] = Variable<String>(fee);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['student'] = Variable<int>(student);
    map['amount'] = Variable<double>(amount);
    {
      map['status'] = Variable<int>(
        $InvoicesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || due != null) {
      map['due'] = Variable<BigInt>(due);
    }
    map['created'] = Variable<BigInt>(created);
    map['updated'] = Variable<BigInt>(updated);
    return map;
  }

  InvoicesCompanion toCompanion(bool nullToAbsent) {
    return InvoicesCompanion(
      id: Value(id),
      school: Value(school),
      year: Value(year),
      term: Value(term),
      fee: fee == null && nullToAbsent ? const Value.absent() : Value(fee),
      description: description == null && nullToAbsent
          ? const Value.absent()
